import{_ as e,c as t,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1785925329000}'),n={name:"guide/installation.md"};function s(l,a,r,p,h,d){return o(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Clipboard x AI is available for macOS.</p><h2 id="download-options" tabindex="-1">Download Options <a class="header-anchor" href="#download-options" aria-label="Permalink to &quot;Download Options&quot;">​</a></h2><h3 id="mac-app-store-recommended" tabindex="-1">Mac App Store (Recommended) <a class="header-anchor" href="#mac-app-store-recommended" aria-label="Permalink to &quot;Mac App Store (Recommended)&quot;">​</a></h3><ul><li><strong>Download</strong>: Search for <strong>Clipboard x AI</strong> on the Mac App Store, or open the link from the <a href="/">home page</a>.</li><li>The Mac App Store version provides automatic updates and seamless macOS integration.</li></ul><blockquote><p>If a Mac App Store link is not yet available, use the GitHub Releases build below.</p></blockquote><h3 id="github-releases-alternative" tabindex="-1">GitHub Releases (Alternative) <a class="header-anchor" href="#github-releases-alternative" aria-label="Permalink to &quot;GitHub Releases (Alternative)&quot;">​</a></h3><p>You can download the latest build directly from <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a>. Note that this version does not receive automatic updates.</p><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Open the download link above or search for &quot;Clipboard x AI&quot; in the Mac App Store.</li><li>Click <strong>Get</strong> to download the app.</li><li>The app installs automatically — launch it from <strong>Applications</strong> or <strong>Launchpad</strong>.</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>Download the latest <code>.dmg</code> from the Releases page.</li><li>Double-click the downloaded <code>.dmg</code> to open it.</li><li>Drag the <code>Clipboard x AI.app</code> icon into your <strong>Applications</strong> folder.</li><li>Eject the mounted image and open the app from <strong>Applications</strong>.</li></ol><p>If macOS prevents opening the app (Gatekeeper), open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong>, or right-click the app and choose <strong>Open</strong>.</p><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><p>On first launch, Clipboard x AI guides you through a short setup:</p><ul><li><strong>Enable the menu bar item</strong> so the app lives in your menu bar.</li><li><strong>Grant permissions</strong> it needs to monitor the clipboard in the background (see <a href="/guide/permissions.html">Permissions</a>).</li><li><em>(Optional)</em> <strong>Connect a cloud AI provider</strong> in <strong>Settings → AI</strong> if you want AI actions.</li></ul><p>Grant permissions when prompted. You can change them any time in <strong>System Settings → Privacy &amp; Security</strong>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><ul><li><strong>Mac App Store version</strong>: updated automatically by the App Store.</li><li><strong>GitHub Releases version</strong>: download the newer release and replace the app in <code>Applications</code>.</li></ul><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>To remove Clipboard x AI:</p><ol><li>Quit the app.</li><li>Drag <code>Clipboard x AI.app</code> from <code>Applications</code> to the Trash.</li><li>(Optional) Remove local data:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma (14) or later</li><li><strong>CPU</strong>: Apple Silicon (M-series) or Intel (64-bit)</li><li><strong>Memory</strong>: 4 GB minimum, 8 GB recommended</li><li><strong>Storage</strong>: ~50 MB</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If you run into problems during installation:</p><ul><li><strong>macOS blocks the app</strong>: Open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong>.</li><li><strong>Notarization warning</strong>: download a signed/notarized build from the Mac App Store.</li></ul><p>For more help, see the <a href="/guide/troubleshooting.html">Troubleshooting guide</a>.</p>`,30)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
